from collections import deque
V = ['A','B','C','D','E']
E = [('A','B'),('B','C'),('C','D'),('D','E'),('C','E')]
def comps(rm_v=None, rm_e=None):
    vs = [v for v in V if v != rm_v]
    es = [e for e in E if rm_e is None or set(e) != set(rm_e)]
    adj = {v: [] for v in vs}
    for u, v in es:
        if u in adj and v in adj:
            adj[u].append(v)
            adj[v].append(u)
    seen = set()
    count = 0
    for s in vs:
        if s not in seen:
            count += 1
            stack = [s]
            seen.add(s)
            while stack:
                x = stack.pop()
                for y in adj[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)
    return count
base = comps()
cut = sum(1 for v in V if comps(rm_v=v) > base)
bridge = sum(1 for e in E if comps(rm_e=e) > base)
adj = {v: [] for v in V}
for u, v in E:
    adj[u].append(v)
    adj[v].append(u)
dist = {v: -1 for v in V}
dist['A'] = 0
q = deque(['A'])
while q:
    x = q.popleft()
    for y in adj[x]:
        if dist[y] < 0:
            dist[y] = dist[x] + 1
            q.append(y)
short = dist['E']
def dist_avoid(u, v, ban):
    d = {x: -1 for x in V}
    d[u] = 0
    qq = deque([u])
    while qq:
        x = qq.popleft()
        for y in adj[x]:
            if {x, y} == set(ban):
                continue
            if d[y] < 0:
                d[y] = d[x] + 1
                qq.append(y)
    return d[v]
girth = min(dist_avoid(u, v, (u, v)) + 1 for u, v in E if dist_avoid(u, v, (u, v)) != -1)
print(short)
print(girth)
print(cut)
print(bridge)
